import type { Metadata } from "next";
import Navbar from "@/components/Navbar";
import Footer from "@/components/Footer";
import ScrollToTop from "@/components/ScrollToTop";
import ScrollReveal from "@/components/ScrollReveal";
import { site } from "@/data";
// Fonts from site.json (theme.fonts), generated by scripts/fonts.mjs.
import { fontVariables } from "./fonts.generated";
import "./globals.css";

export const metadata: Metadata = {
  title: site.site.title,
  description: site.site.description,
};

// Colours come from site.json (theme.colors) and override the globals.css defaults; invalid values are skipped.
const isHex = (v: string) => /^#([0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i.test(v);
const themeCss = `:root{${Object.entries(site.theme.colors)
  .filter(([, v]) => isHex(v))
  .map(([k, v]) => `--color-${k}:${v}`)
  .join(";")}}`;

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html
      lang={site.site.lang}
      data-scroll-behavior="smooth"
      // Root font size: 16px, and from 1024px up it follows the 1920px design (1 design px = 1/1920 of the screen).
      // Tailwind v4 leaves buttons on the default cursor, so everything clickable gets the pointer.
      className={`${fontVariables} scroll-smooth antialiased [font-size:16px] xl:[font-size:min(16px,calc(100vw/120))] [&_:where(a[href],button:not(:disabled),select,[role=button])]:cursor-pointer motion-reduce:scroll-auto`}
    >
      <head>
        <style dangerouslySetInnerHTML={{ __html: themeCss }} />
      </head>
      <body className="bg-cloud font-heading text-heading">
        <ScrollReveal />
        {/*
          The site never grows wider than the 1920px design (120rem = 1920px once the root
          font size stops growing), so on wide screens or when zoomed out it stays centred
          instead of stretching. Up to 1920px it is simply the full width.
        */}
        <div className="mx-auto flex min-h-screen w-full max-w-[120rem] flex-col overflow-x-clip bg-white">
          <Navbar />
          <main className="flex-1">
            <ScrollToTop>{children}</ScrollToTop>
          </main>
          <Footer />
        </div>
      </body>
    </html>
  );
}
